(* |- x <= 0 \/ 1 <= x (integer trichotomy; probes boolean/case rules) *)
Theorem corpus_lia_disjunction :
  forall x : Z, x <= 0 \/ 1 <= x.
Proof. intros x. alethe_walker_test "(
(assume a0 (! (not (! (or (! (<= x 0) :named @p_2) (! (<= 1 x) :named @p_1)) :named @p_3)) :named @p_4))
(step t0 (cl (not (! (not (! (not (! (>= x 1) :named @p_5)) :named @p_6)) :named @p_12)) @p_5) :rule not_not)
(step t1 (cl (not (! (= @p_4 (! (not (! (or @p_6 @p_5) :named @p_7)) :named @p_8)) :named @p_9)) (not @p_4) @p_8) :rule equiv_pos2)
(step t2 (cl (! (= @p_2 @p_6) :named @p_11)) :rule hole :args (""TRUST_THEORY_REWRITE"" @p_11 3 7))
(step t3 (cl (! (= @p_1 @p_5) :named @p_10)) :rule hole :args (""TRUST_THEORY_REWRITE"" @p_10 3 7))
(step t4 (cl (= @p_3 @p_7)) :rule cong :premises (t2 t3))
(step t5 (cl @p_9) :rule cong :premises (t4))
(step t6 (cl @p_8) :rule resolution :premises (t1 t5 a0))
(step t7 (cl @p_12) :rule not_or :premises (t6) :args (0))
(step t8 (cl @p_5) :rule resolution :premises (t0 t7))
(step t9 (cl @p_6) :rule not_or :premises (t6) :args (1))
(step t10 (cl) :rule resolution :premises (t8 t9))
)". Qed.

